/**
 * DÉMARRER UNE PRÉSENTATION SYNCHRONISÉE
 *
 * Tous les utilisateurs du monde observeront le même terminal. Le contrôleur
 * choisi navigue librement; le MJ n’a pas à confirmer chaque action.
 *
 * TERMINAL_UUID : UUID du Journal Terminal à présenter.
 * CONTROLLER : nom exact ou ID d’un utilisateur connecté. Une chaîne vide
 * utilise le MJ qui exécute la macro.
 *
 * Important : tous les utilisateurs doivent avoir la permission Observateur
 * sur le Journal et pouvoir voir sa page d’accueil.
 */

// ── CONFIGURATION À MODIFIER ──────────────────────────────────
const TERMINAL_UUID = "JournalEntry.REMPLACEZ_MOI";
const CONTROLLER = ""; // Exemple : "Alice" ou "abc123UserId"
// ──────────────────────────────────────────────────────────────

if (!game.user.isGM) return ui.notifications.error("Cette macro est réservée au MJ.");
const api = game.modules.get("retro-crt-terminal")?.api;
if (!api) return ui.notifications.error("Retro CRT Terminal n’est pas actif.");
if (!TERMINAL_UUID || TERMINAL_UUID.includes("REMPLACEZ_MOI")) {
  return ui.notifications.warn("Modifiez TERMINAL_UUID dans la configuration de la macro.");
}

const controller = CONTROLLER
  ? game.users.get(CONTROLLER) ?? game.users.find(user => user.name === CONTROLLER)
  : game.user;
if (!controller) return ui.notifications.error(`Utilisateur introuvable : ${CONTROLLER}`);
if (!controller.active) return ui.notifications.error(`${controller.name} n’est pas connecté.`);

await api.shared.start({
  terminalRootUuid: TERMINAL_UUID,
  controllerUserId: controller.id
});
ui.notifications.info(`Présentation démarrée — contrôle : ${controller.name}`);
